+func TestYAMLEscapedQuoteComments(t *testing.T) {
+	for _, tc := range []struct {
+		name, scalar, want string
+	}{
+		{"escaped quote hash", `"before \" # inside and all following text"`, `before " # inside and all following text`},
+		{"closing quote comment", `"before \" # inside and all following text" # outside comment`, `before " # inside and all following text`},
+		{"escaped backslash closing quote", `"ends with a backslash \\" # outside comment`, `ends with a backslash \`},
+		{"single quote", `'it''s # not a comment' # outside comment`, `it's # not a comment`},
+		{"plain", `some text, with [brackets] # outside comment`, `some text, with [brackets]`},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			node, problems := parseYAML("value: " + tc.scalar + "\n")
+			if len(problems) != 0 || node == nil {
+				t.Fatalf("parseYAML: %v", problems)
+			}
+			if got := node.pairs[0].node.text; got != tc.want {
+				t.Fatalf("got %q, want %q", got, tc.want)
+			}
+		})
+	}
+}

